2	
3	import (
4		"bytes"
5		"context"
6		"io"
7		"net/http"
8		"net/http/httptest"
9		"net/url"
10		"strings"
11		"sync"
12		"sync/atomic"
13		"testing"
14		"time"
15	)
16	
17	// authRecorder collects values captured inside an httptest handler
18	// goroutine for assertion in the test goroutine. HTTP completion isn't a
19	// happens-before edge the race detector recognises (see
20	// client_test.go:160-189), so the mutex makes the cross-goroutine reads
21	// race-safe under `-race`.
22	type authRecorder struct {
23		mu   sync.Mutex
24		vals []string
25	}
26	
27	func (a *authRecorder) add(v string) {
28		a.mu.Lock()
29		defer a.mu.Unlock()
30		a.vals = append(a.vals, v)
31	}
32	
33	func (a *authRecorder) snapshot() []string {
34		a.mu.Lock()
35		defer a.mu.Unlock()
36		return append([]string(nil), a.vals...)
37	}
38	
39	// crossJurisTestServer scripts responses keyed by the caller-controlled
40	// handler and records the Authorization header per request so tests can
41	// assert which token the transport presented on each hop. It auto-serves
42	// GET /.well-known/entire-federation with the hosts in `peers`.
43	type crossJurisTestServer struct {
44		hits  atomic.Int32
45		auths authRecorder
46		peers []string
47		srv   *httptest.Server
48	}
49	
50	func (s *crossJurisTestServer) record(r *http.Request) {
51		s.hits.Add(1)
52		s.auths.add(r.Header.Get("Authorization"))
53	}
54	
55	func newCrossJurisTestServer(t *testing.T, handler func(s *crossJurisTestServer, w http.ResponseWriter, r *http.Request)) *crossJurisTestServer {
56		t.Helper()
57		s := &crossJurisTestServer{}
58		s.srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
59			if r.URL.Path == "/.well-known/entire-federation" {
60				writeTestFederation(w, s.peers)
61				return
62			}
63			handler(s, w, r)
64		}))
65		t.Cleanup(s.srv.Close)
66		return s
67	}
68	
69	func writeTestFederation(w http.ResponseWriter, peers []string) {
70		w.Header().Set("Content-Type", "application/json")
71		w.WriteHeader(http.StatusOK)
72		if len(peers) == 0 {
73			w.Write([]byte(`{"peer_auth_hosts":[]}`)) //nolint:errcheck // test
74			return
75		}
76		var b strings.Builder
77		b.WriteString(`{"peer_auth_hosts":[`)
78		for i, p := range peers {
79			if i > 0 {
80				b.WriteString(",")
81			}
82			b.WriteString(`"`)
83			b.WriteString(p)
84			b.WriteString(`"`)
85		}
86		b.WriteString(`]}`)
87		w.Write([]byte(b.String())) //nolint:errcheck // test
88	}
89	
90	func transportFor() *crossJurisRoundTripper {
91		return newCrossJurisRoundTripper(http.DefaultTransport)
92	}
93	
94	// TestRoundTripper_PassThrough: a 2xx is returned unchanged.
95	func TestRoundTripper_PassThrough(t *testing.T) {
96		srv := newCrossJurisTestServer(t, func(s *crossJurisTestServer, w http.ResponseWriter, r *http.Request) {
97			s.record(r)
98			w.WriteHeader(http.StatusOK)
99			w.Write([]byte(`{"ok":true}`)) //nolint:errcheck // test
100		})
101	
102		client := &http.Client{Transport: transportFor()}
103		req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, srv.srv.URL, nil) //nolint:errcheck // test
104		req.Header.Set("Authorization", "Bearer user-jwt")
105	
106		resp, err := client.Do(req)
107		if err != nil {
108			t.Fatal(err)
109		}
110		defer resp.Body.Close()
111		if resp.StatusCode != http.StatusOK {
112			t.Fatalf("got %d", resp.StatusCode)
113		}
114		if srv.hits.Load() != 1 {
115			t.Fatalf("hits=%d", srv.hits.Load())
116		}
117	}
118	
119	// TestRoundTripper_421FollowsToHomeCore: 421 with home_core_url is
120	// followed; the home core gets the original bearer on the first hop.
121	func TestRoundTripper_421FollowsToHomeCore(t *testing.T) {
122		homeCore := newCrossJurisTestServer(t, func(s *crossJurisTestServer, w http.ResponseWriter, r *http.Request) {
123			s.record(r)
124			w.WriteHeader(http.StatusOK)
125		})
126		wrongCore := newCrossJurisTestServer(t, func(s *crossJurisTestServer, w http.ResponseWriter, r *http.Request) {
127			s.record(r)
128			w.WriteHeader(http.StatusMisdirectedRequest)
129			w.Write([]byte(`{"home_core_url":"` + homeCore.srv.URL + `"}`)) //nolint:errcheck // test
130		})
131		wrongCore.peers = []string{homeCore.srv.URL}
132	
133		client := &http.Client{Transport: transportFor()}
134		req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, wrongCore.srv.URL+"/api/v1/mirrors", strings.NewReader(`{"a":1}`)) //nolint:errcheck // test
135		req.Header.Set("Authorization", "Bearer user-jwt")
136	
137		resp, err := client.Do(req)
138		if err != nil {
139			t.Fatal(err)
140		}
141		defer resp.Body.Close()
142		if resp.StatusCode != http.StatusOK {
143			t.Fatalf("got %d", resp.StatusCode)
144		}
145		if got := homeCore.auths.snapshot(); len(got) == 0 || got[0] != "Bearer user-jwt" {
146			t.Fatalf("home core first hop auth = %v", got)
147		}
148	}
149	
