	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("got %d", resp.StatusCode)
	}
	if srv.hits.Load() != 1 {
		t.Fatalf("hits=%d", srv.hits.Load())
	}
